const allowed = new Set(['ATLAS','NOVA','PULSE','VITALIS','ARTEMIS','SERENA','KAOS','AION','GENUS','LUMINE','RHEA','SOLUS','KODUX','BLLUE','JESUS','KOBLLUX']);
const input = $input.first().json.body ?? $input.first().json;
if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Expected an event object');
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(input.event_id ?? '')) throw new Error('Invalid event_id');
if (!['sumbus-fusion/hypervision','github-actions'].includes(input.source)) throw new Error('Invalid source');
if (!Array.isArray(input.archetypes) || !input.archetypes.length || input.archetypes.length > 16) throw new Error('Invalid archetypes');
const archetypes = [...new Set(input.archetypes.map(value => String(value).toUpperCase()))];
if (archetypes.some(value => !allowed.has(value))) throw new Error('Unknown archetype');
if (!Array.isArray(input.tags) || input.tags.length > 32 || input.tags.some(tag => typeof tag !== 'string' || !tag.trim() || tag.length > 80)) throw new Error('Invalid tags');
if (typeof input.ts !== 'string' || Number.isNaN(Date.parse(input.ts))) throw new Error('Invalid timestamp');
if (!input.payload || typeof input.payload !== 'object' || Array.isArray(input.payload) || JSON.stringify(input.payload).length > 12000) throw new Error('Invalid payload');
return [{json:{event_id:input.event_id,occurred_at:new Date(input.ts).toISOString(),source:input.source,archetypes,tags:[...new Set(input.tags)],payload:input.payload}}];
